import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

l2norm_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// Kernel to compute partial squared sums per row
__global__ void partial_sum_kernel(const float* __restrict__ x,
                                   float* __restrict__ partial_sums,
                                   int batch,
                                   int dim) {
    int row = blockIdx.x;
    float sum_val = 0.0f;

    // Accumulate partial sums of squares
    for (int i = threadIdx.x; i < dim; i += blockDim.x) {
        float val = x[row * dim + i];
        sum_val += val * val;
    }

    // Reduce within block
    __shared__ float smem[1024];  // Assuming blockDim.x <= 1024
    smem[threadIdx.x] = sum_val;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            smem[threadIdx.x] += smem[threadIdx.x + s];
        }
        __syncthreads();
    }

    // Write result for the row
    if (threadIdx.x == 0) {
        partial_sums[row] = smem[0];
    }
}

// Kernel to divide each element by its row norm
__global__ void division_kernel(const float* __restrict__ x,
                                const float* __restrict__ partial_sums,
                                float* __restrict__ out,
                                int batch,
                                int dim) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch * dim;
    if (idx < total) {
        int row = idx / dim;
        float norm = sqrtf(partial_sums[row]);
        out[idx] = (norm > 0.0f) ? (x[idx] / norm) : 0.0f;
    }
}

torch::Tensor l2norm_cuda(torch::Tensor x) {
    // Ensure 2D
    TORCH_CHECK(x.dim() == 2, "Input must be a 2D tensor");
    int batch = x.size(0);
    int dim = x.size(1);

    auto out = torch::zeros_like(x);
    auto partial_sums = torch::zeros({batch}, x.options());

    const int block_size = 1024;

    // Launch kernel to compute squared sums
    partial_sum_kernel<<<batch, block_size>>>(x.data_ptr<float>(),
                                              partial_sums.data_ptr<float>(),
                                              batch,
                                              dim);

    // Launch kernel for division
    int total = batch * dim;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;
    division_kernel<<<blocks, threads>>>(x.data_ptr<float>(),
                                         partial_sums.data_ptr<float>(),
                                         out.data_ptr<float>(),
                                         batch,
                                         dim);

    return out;
}
"""

l2norm_cpp_source = r"torch::Tensor l2norm_cuda(torch::Tensor x);"

l2norm_custom = load_inline(
    name="l2norm_custom",
    cpp_sources=l2norm_cpp_source,
    cuda_sources=l2norm_source,
    functions=["l2norm_cuda"],
    verbose=False,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.l2norm_custom = l2norm_custom

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.l2norm_custom.l2norm_cuda(x)
